exercises.solution:
const RETRYABLE_STATUS = new Set([408, 429, 500, 502, 503, 504]);
const IDEMPOTENT = new Set(['GET', 'HEAD', 'OPTIONS', 'PUT', 'DELETE']);
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function retryAfterMs(res) {
  const value = res.headers.get('retry-after');
  if (!value) return null;
  const seconds = Number(value);
  if (Number.isFinite(seconds)) return seconds * 1000;
  const date = Date.parse(value);
  return Number.isNaN(date) ? null : Math.max(0, date - Date.now());
}

async function fetchWithRetry(url, options = {}, { retries = 3, baseMs = 200, timeoutMs = 5000 } = {}) {
  const method = (options.method || 'GET').toUpperCase();
  const canRetry = IDEMPOTENT.has(method);

  for (let attempt = 0; ; attempt++) {
    const backoff = Math.random() * baseMs * 2 ** attempt; // full jitter
    try {
      const res = await fetch(url, { ...options, signal: AbortSignal.timeout(timeoutMs) });
      if (!canRetry || !RETRYABLE_STATUS.has(res.status) || attempt >= retries) return res;
      await sleep(retryAfterMs(res) ?? backoff);
    } catch (err) {
      // network error or timeout
      if (!canRetry || attempt >= retries) throw err;
      await sleep(backoff);
    }
  }
}
